module Moderate
  class BaseController < ApplicationController
    prepend_before_action :authenticate_moderator

    private

    def authenticate_moderator
      no_store
      username = ENV["QUIZZY_MODERATOR_USERNAME"]
      password = ENV["QUIZZY_MODERATOR_PASSWORD"]

      if username.present? && password.present?
        http_basic_authenticate_or_request_with(name: username, password: password, realm: "Quizzy")
      else
        request_http_basic_authentication("Quizzy")
      end
    end
  end
