  class QuestionsController < BaseController
    before_action :set_quiz
    before_action :set_question, only: %i[edit update destroy move set_active]

    def new
      @question = @quiz.questions.build(option_rows: Array.new(4) { {} })
      render :form
    end

    def create
      @question = @quiz.questions.build
      save_question
    end

    def edit
      render :form
    end

    def update
      save_question
    end

    def destroy
      @question.destroy!
      return_to_quiz
    end

    def move
      direction = params.expect(:direction)
      raise ActionController::BadRequest, "Unknown move direction" unless %w[up down].include?(direction)

      @question.move(direction)
      return_to_quiz
    end

    def set_active
      active = params.expect(:active)
      raise ActionController::BadRequest, "Invalid active value" unless %w[0 1].include?(active)

      @question.update!(active: active)
      return_to_quiz
    end

    private

    def set_quiz
      @quiz = Quiz.find(params[:quiz_id])
    end

    def set_question
      @question = @quiz.questions.find(params[:id])
    end

    def save_question
      fields = params.expect(question: [ :body, :active, option_rows: [ [ :text, :correct ] ] ])
      rows = fields.delete(:option_rows)
      @question.assign_attributes(fields)
      @question.option_rows = rows.is_a?(ActionController::Parameters) ? rows.values : Array(rows)

      if @question.save
        return_to_quiz
      else
        render :form, status: :unprocessable_content
      end
    end

    def return_to_quiz
      redirect_to moderate_quiz_path(@quiz), status: :see_other
    end
  end
